// The recommendation-sorting 3.1 duty: the scored default on the series and
// item listings (score desc, ties by served display name then id), the
// sort=path opt-out, and D7's score-then-window on the item listing — all
// asserted over the REAL router wiring and a real store, the tag chain
// injected through the ModulePresentation seam exactly as cmd wires it.

const recsMetaNS = "test-meta"

// newRecsAPI builds the router over a fresh store with one chained library:
// a gate-resolved-looking source chain of ONE enabled namespace, so genresFor
// resolves tags off documents carrying it.
func newRecsAPI(t *testing.T) (http.Handler, *store.Store, int64) {
	t.Helper()
	st := openAPIStore(t)
	h := New(Deps{
		AdminToken: adminToken,
		Store:      st,
		ModulePresentation: func(_ context.Context, _ string, _ int64) (ModulePresentation, error) {
			return ModulePresentation{SourceChain: []titleSourceBinding{{ID: recsMetaNS, Enabled: true}}}, nil
		},
	})
	libID, err := st.CreateLibrary(context.Background(), "serial", "/media/recs", "Recs")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	return h, st, libID
}

// recsDoc marshals a document map (panics are fine: the input is a test
// literal, a marshal failure is a test bug).
func recsDoc(t *testing.T, doc map[string]any) json.RawMessage {
	t.Helper()
	b, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal doc: %v", err)
	}
	return b
}

// recsSeriesDoc is a series document carrying the namespace's synopsis group
// (the carrier test is the description) with its genres ride-along, plus the
// display floor dir_name_raw.
func recsSeriesDoc(dir string, genres ...string) map[string]any {
	doc := map[string]any{
		"parsed": map[string]any{"backing": "directory", "dir_name_raw": dir},
	}
	if genres != nil {
		doc["sources"] = map[string]any{
			recsMetaNS: map[string]any{"description": "d", "genres": genres},
		}
	}
	return doc
}

// seedRecsSeries puts one series row in and returns the stored row (minted
// ser_ id included).
func seedRecsSeries(t *testing.T, st *store.Store, libraryID int64, path string, doc map[string]any) store.Series {
	t.Helper()
	if err := st.PutSeries(context.Background(), store.Series{
		ModuleID: "serial", LibraryID: libraryID, RelativePath: path,
		Document: recsDoc(t, doc), SchemaVersion: 1, Status: "ready",
	}); err != nil {
		t.Fatalf("PutSeries %s: %v", path, err)
	}
	sr, err := st.GetSeriesByPath(context.Background(), libraryID, path, access.System())
	if err != nil {
		t.Fatalf("GetSeriesByPath %s: %v", path, err)
	}
	return sr
}

// seedRecsItem puts one item row (id is the file id too) and returns the
// stored row; createdAt zero means discovered now (the store floors a zero
// created_at to now).
func seedRecsItem(t *testing.T, st *store.Store, libraryID int64, id, relPath string, doc map[string]any, createdAt time.Time) store.Item {
	t.Helper()
	if err := st.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "serial", LibraryID: libraryID, FileID: id,
		RelativePath: relPath, MediaType: "serial",
		Document: recsDoc(t, doc), SchemaVersion: 1, CreatedAt: createdAt,
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
	got, err := st.GetItem(context.Background(), id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return got
}

// recsEpisodeDoc is an episode document anchored to its series, optionally
// carrying a _view title (the display floor under no template).
func recsEpisodeDoc(seriesPath, viewTitle string) map[string]any {
	doc := map[string]any{"parsed": map[string]any{"series_relative_path": seriesPath}}
	if viewTitle != "" {
		doc["_view"] = map[string]any{"title": map[string]any{"value": viewTitle}}
	}
	return doc
}

// decodeItems/decodeSeries decode the two listing wire shapes.
func decodeItems(t *testing.T, resp *http.Response) itemsResponse {
	t.Helper()
	var lr itemsResponse
	if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
		t.Fatalf("decode itemsResponse: %v", err)
	}
	return lr
}

// servedIDs extracts the listing's id order.
func servedIDs[T any](items []T, id func(T) string) []string {
	out := make([]string, len(items))
	for i, d := range items {
		out[i] = id(d)
	}
	return out
}

// wantIDs asserts the served id order.
func wantIDs(t *testing.T, got []string, want ...string) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("served %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("served %v, want %v", got, want)
		}
	}
}

// TestListSeriesScored covers the series listing's scored default: tier
// dominance (started-with-new-episode > in-progress > weighted tags > plain),
// the display-name tie-break on equal scores (NOT path order), the D3 window
// bound, and the sort=path opt-out serving today's relative_path order
// unscored.
func TestListSeriesScored(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// All rows seeded up front (the subtests share one library state), in an
	// order deliberately different from every expected output order.
	plain := seedRecsSeries(t, st, lib, "dd-plain", recsSeriesDoc("Plain")) // no genres → 0
	tagged := seedRecsSeries(t, st, lib, "cc-tagged", recsSeriesDoc("Tagged", "action", "thriller"))
	if err := st.ApplyTagWeights(ctx, []string{"action", "thriller", "thriller"}, time.Now().UTC()); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}
	// interest action=1, thriller=2 → tag component (1+1)+(1+2) = 5
	watched := seedRecsSeries(t, st, lib, "aa-watched", recsSeriesDoc("Watched"))
	epWatched := seedRecsItem(t, st, lib, "itm_w1", "aa-watched/e1.mkv", recsEpisodeDoc("aa-watched", ""), time.Time{})
	if _, err := st.PutProgress(ctx, epWatched.ID, 300, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	ongoing := seedRecsSeries(t, st, lib, "bb-ongoing", recsSeriesDoc("Ongoing"))
	epStarted := seedRecsItem(t, st, lib, "itm_o1", "bb-ongoing/e1.mkv", recsEpisodeDoc("bb-ongoing", ""), time.Time{})
	if _, err := st.PutProgress(ctx, epStarted.ID, 100, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	seedRecsItem(t, st, lib, "itm_o2", "bb-ongoing/e2.mkv", recsEpisodeDoc("bb-ongoing", ""), time.Time{}) // fresh + unwatched → 1500
	// The D3 window bound: a started series whose only unwatched episode is
	// stale (discovered outside NEW_WINDOW) scores in-progress alone.
	stale := seedRecsSeries(t, st, lib, "ee-stale", recsSeriesDoc("Stale"))
	epStaleOld := seedRecsItem(t, st, lib, "itm_s1", "ee-stale/e1.mkv", recsEpisodeDoc("ee-stale", ""), time.Now().AddDate(0, 0, -40))
	if _, err := st.PutProgress(ctx, epStaleOld.ID, 50, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	seedRecsItem(t, st, lib, "itm_s2", "ee-stale/e2.mkv", recsEpisodeDoc("ee-stale", ""), time.Now().AddDate(0, 0, -40))
	// Two unstarted untagged series tie at 0: the floor is the SERVED
	// display name, so Zeta (path a-) ranks before Alpha (path b-) — path
	// order would serve the reverse.
	zeta := seedRecsSeries(t, st, lib, "a-path", recsSeriesDoc("Zeta"))
	alpha := seedRecsSeries(t, st, lib, "b-path", recsSeriesDoc("Alpha"))

	t.Run("tier_dominance_and_rec_score", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		rows := decodeSeriesList(t, resp)
		got := servedIDs(rows, func(d seriesDTO) string { return d.ID })
		wantIDs(t, got, ongoing.ID, stale.ID, watched.ID, tagged.ID, alpha.ID, plain.ID, zeta.ID)
		wantScores := map[string]float64{
			ongoing.ID: 1500, watched.ID: 1000, stale.ID: 1000,
			tagged.ID: 5, alpha.ID: 0, plain.ID: 0, zeta.ID: 0,
		}
		for _, d := range rows {
			if d.RecScore != wantScores[d.ID] {
				t.Fatalf("series %s rec_score = %v, want %v", d.ID, d.RecScore, wantScores[d.ID])
			}
		}
	})

	t.Run("display_name_tiebreak_beats_path_order", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib), "", adminToken)
		defer resp.Body.Close()
		rows := decodeSeriesList(t, resp)
		var got []string
		for _, d := range rows {
			if d.RecScore == 0 {
				got = append(got, d.ID)
			}
		}
		wantIDs(t, got, alpha.ID, plain.ID, zeta.ID)
	})

	t.Run("sort_path_restores_today_unscored", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib)+"&sort=path", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		rows := decodeSeriesList(t, resp)
		got := servedIDs(rows, func(d seriesDTO) string { return d.ID })
		// QuerySeries' relative_path order, byte for byte.
		wantIDs(t, got, zeta.ID, watched.ID, alpha.ID, ongoing.ID, tagged.ID, plain.ID, stale.ID)
		for _, d := range rows {
			if d.RecScore != 0 {
				t.Fatalf("sort=path computed scores (%v on %s) — the opt-out must serve unscored", d.RecScore, d.ID)
			}
		}
	})

	t.Run("unknown_sort_is_400", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib)+"&sort=recent", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want 400", resp.StatusCode)
		}
	})
}

// TestListItemsScored covers the item listing's scored default: the tier
// order over films and episodes, episode tags joined from the series
// document (D1), the watched partition (a completed item sinks below every
// unwatched row and scores tags-only — the resume bonus is skipped), the
// display-name tie-break at the top tier, the zero-score
// omission, and D7's score-then-window — the page cut applies AFTER the
// score order, so no page can outrank page 1.
func TestListItemsScored(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Films (no series anchor; tags from the item's own document). The
	// watched film carries BOTH facts the detector writes — the positive
	// position AND the ledger row — so it is genuinely completed: its resume
	// bonus is skipped (tags-only score) and the partition sinks it below
	// every unwatched row whatever their scores.
	watchedFilm := seedRecsItem(t, st, lib, "itm_f1", "film-a.mkv", map[string]any{
		"_view":   map[string]any{"title": map[string]any{"value": "AAA watched"}},
		"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"action"}}},
	}, time.Time{})
	if _, err := st.PutProgress(ctx, watchedFilm.ID, 600, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	if err := st.InsertWatched(ctx, watchedFilm.ID, lib, "", time.Now().UTC(), access.System()); err != nil {
		t.Fatalf("InsertWatched: %v", err)
	}
	taggedFilm := seedRecsItem(t, st, lib, "itm_f2", "film-b.mkv", map[string]any{
		"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"thriller"}}},
	}, time.Time{})
	if err := st.ApplyTagWeights(ctx, []string{"action", "thriller", "thriller"}, time.Now().UTC()); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}
	// interest action=1, thriller=2 — the watched film's tags-only score is
	// base 1 + the action weight = 2; the tagged film's is 1 + 2 = 3.
	plainFilm := seedRecsItem(t, st, lib, "itm_f3", "film-c.mkv", map[string]any{}, time.Time{}) // score 0 → omitted

	// A started serial with a fresh unwatched episode: the new episode item
	// carries the 500 tier, its tags joined from the SERIES document (the
	// episode documents here carry no sources at all).
	seedRecsSeries(t, st, lib, "show", recsSeriesDoc("Show", "drama"))
	epStarted := seedRecsItem(t, st, lib, "itm_e1", "show/e1.mkv", recsEpisodeDoc("show", "Mid Episode"), time.Time{})
	if _, err := st.PutProgress(ctx, epStarted.ID, 100, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	epNew := seedRecsItem(t, st, lib, "itm_e2", "show/e2.mkv", recsEpisodeDoc("show", ""), time.Time{}) // started series + fresh → 500 + drama

	listURL := "/api/v1/items?library=" + itoa64(lib)

	t.Run("scored_default_order", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, listURL, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		got := servedIDs(lr.Items, func(d itemDTO) string { return d.ID })
		// The watched partition sinks the completed film below every
		// unwatched row, whatever the scores: the unwatched page keeps its
		// tier order — the started episode (1000 + its drama tag joined from
		// the SERIES document — D1), the new episode (500 + the joined tag),
		// the weighted film, the plain film — and the completed film serves
		// LAST at its tags-only score (1 base + the action weight; the
		// resume bonus is skipped).
		wantIDs(t, got, epStarted.ID, epNew.ID, taggedFilm.ID, plainFilm.ID, watchedFilm.ID)
		wantScores := map[string]float64{
			watchedFilm.ID: 2, epStarted.ID: 1001, epNew.ID: 501, taggedFilm.ID: 3,
		}
		for _, d := range lr.Items {
			if want, has := wantScores[d.ID]; has && d.RecScore != want {
				t.Fatalf("item %s rec_score = %v, want %v", d.ID, d.RecScore, want)
			}
		}
	})

	t.Run("zero_score_omitted_from_wire", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, listURL, "", adminToken)
		defer resp.Body.Close()
		lr := decodeItems(t, resp)
		for _, d := range lr.Items {
			b, err := json.Marshal(d)
			if err != nil {
				t.Fatalf("remarshal %s: %v", d.ID, err)
			}
			var wire map[string]any
			if err := json.Unmarshal(b, &wire); err != nil {
				t.Fatalf("unmarshal %s: %v", d.ID, err)
			}
			_, has := wire["rec_score"]
			if d.ID == plainFilm.ID && has {
				t.Fatalf("zero-score item %s served rec_score — omitempty must omit it", d.ID)
			}
			if d.ID != plainFilm.ID && !has {
				t.Fatalf("scored item %s omitted rec_score", d.ID)
			}
		}
	})

	t.Run("score_then_window", func(t *testing.T) {
		// D7: the page cut applies AFTER the score order. Page 1 (limit 1)
		// must be the served top row — the started episode, the partition
		// having sunk the completed film below every unwatched one; page 2
		// the second; a page past the end is empty — never unscored
		// lr.Items.
		resp := doRequest(t, h, http.MethodGet, listURL+"&limit=1", "", adminToken)
		defer resp.Body.Close()
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), epStarted.ID)

		resp = doRequest(t, h, http.MethodGet, listURL+"&limit=1&offset=1", "", adminToken)
		defer resp.Body.Close()
		lr = decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), epNew.ID)

		resp = doRequest(t, h, http.MethodGet, listURL+"&limit=50&offset=5", "", adminToken)
		defer resp.Body.Close()
		lr = decodeItems(t, resp)
		if len(lr.Items) != 0 {
			t.Fatalf("offset past the scored set served %d lr.Items, want 0", len(lr.Items))
		}
	})
}

// TestListItemsSortPath covers the opt-out on the item listing: sort=path
// keeps QueryItems' id-ordered SQL window byte-for-byte (the scored order
// would invert it) and serves unscored lr.Items.
func TestListItemsSortPath(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// id order: itm_a (score 0) before itm_b (score 1000) — the scored
	// default inverts exactly this.
	a := seedRecsItem(t, st, lib, "itm_a", "aaa.mkv", map[string]any{}, time.Time{})
	b := seedRecsItem(t, st, lib, "itm_b", "bbb.mkv", map[string]any{}, time.Time{})
	if _, err := st.PutProgress(ctx, b.ID, 900, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}

	t.Run("sort_path_serves_id_order_unscored", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&sort=path", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), a.ID, b.ID)
		for _, d := range lr.Items {
			if d.RecScore != 0 {
				t.Fatalf("sort=path computed scores (%v on %s)", d.RecScore, d.ID)
			}
		}
	})

	t.Run("default_inverts_to_score_order", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib), "", adminToken)
		defer resp.Body.Close()
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), b.ID, a.ID)
	})

	t.Run("sort_path_windows_in_sql", func(t *testing.T) {
		// The opt-out keeps the store's own window: one row per page, in id
		// order.
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&sort=path&limit=1&offset=1", "", adminToken)
		defer resp.Body.Close()
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), b.ID)
	})
}
